    40	export function makeGrassMaterial() {
    41	  const size = 128, canvas = document.createElement("canvas");
    42	  canvas.width = canvas.height = size;
    43	  const ctx = canvas.getContext("2d")!;
    44	  ctx.fillStyle = "#758655";
    45	  ctx.fillRect(0, 0, size, size);
    46	  let state = 6219;
    47	  const sample = () => {
    48	    state = (state * 1664525 + 1013904223) >>> 0;
    49	    return state / 4294967296;
    50	  };
    51	  for (let i = 0; i < 24; i++) {
    52	    const x = sample() * size, y = sample() * size;
    53	    const radius = 13 + sample() * 18;
    54	    const tint = i % 2 ? "148,159,104" : "81,102,62";
    55	    const wrapX = x < radius ? size : x > size - radius ? -size : 0;
    56	    const wrapY = y < radius ? size : y > size - radius ? -size : 0;
    57	    for (const sx of wrapX ? [0, wrapX] : [0]) for (const sy of wrapY ? [0, wrapY] : [0]) {
    58	      const cx = x + sx, cy = y + sy;
    59	      const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
    60	      gradient.addColorStop(0, `rgba(${tint},0.16)`);
    61	      gradient.addColorStop(0.65, `rgba(${tint},0.05)`);
    62	      gradient.addColorStop(1, `rgba(${tint},0)`);
    63	      ctx.fillStyle = gradient;
    64	      ctx.fillRect(cx - radius, cy - radius, radius * 2, radius * 2);
    65	    }
    66	  }
    67	  const map = new T.CanvasTexture(canvas);
    68	  map.wrapS = map.wrapT = T.RepeatWrapping;
    69	  map.colorSpace = T.SRGBColorSpace;
    70	  map.minFilter = T.LinearMipmapLinearFilter;
    71	  map.anisotropy = 16;
    72	  return tiled(map, [6, 6], { roughness: 1 });
    73	}
