   112	    ctx.lineTo(x, y - radius * 0.7);
   113	    ctx.lineTo(x + radius, y - radius * 0.25);
   114	    ctx.lineTo(x + radius * 0.5, y + radius * 0.7);
   115	    ctx.fill();
