```ts
function curvedBed(length, depth, bulge) {
  const halfLength = length/2, halfDepth = depth/2;
  const straight = Math.max(0.15, halfLength - halfDepth);
  const points: Vec2[] = [];
  const push = (p: Vec2) => { const last = points[points.length-1]; if (!last || Math.hypot(p[0]-last[0], p[1]-last[1]) > 1e-6) points.push(p); };
  for (let i = 0; i <= 12; i++) { const t = i/12; push([-straight + 2*straight*t, halfDepth + bulge*Math.sin(Math.PI*t)]); }
  for (let i = 1; i <= 12; i++) { const a = Math.PI/2 - Math.PI*i/12; push([straight + Math.cos(a)*halfDepth, Math.sin(a)*halfDepth]); }
  for (let i = 1; i <= 12; i++) { const t = 1 - i/12; push([-straight + 2*straight*t, -halfDepth - bulge*Math.sin(Math.PI*t)]); }
  for (let i = 1; i < 12; i++) { const a = -Math.PI/2 - Math.PI*i/12; push([-straight + Math.cos(a)*halfDepth, Math.sin(a)*halfDepth]); }
  return points;
